from datetime import datetime, timedelta, timezone
from typing import Optional

from sqlalchemy import delete
from sqlalchemy.orm import Session

from app.models import Customer

CUSTOMER_RETENTION_DAYS = 730


def purge_expired_customers(session: Session, reference: Optional[datetime] = None) -> int:
    now = reference or datetime.now(timezone.utc)
    cutoff = now - timedelta(days=CUSTOMER_RETENTION_DAYS)

    expired_ids = [
        row[0]
        for row in session.query(Customer.id).filter(Customer.deleted_at < cutoff).all()
    ]
    if not expired_ids:
        return 0

    session.execute(delete(Customer).where(Customer.id.in_(expired_ids)))
    session.commit()
    return len(expired_ids)


def run_nightly(session_factory) -> int:
    with session_factory() as session:
        return purge_expired_customers(session)

