logger = logging.getLogger(__name__)


@shared_task(bind=True, max_retries=3, default_retry_delay=60)
def notify_customer_about_delivery(self, customer_id: int, tracking_code: str):
    try:
        customer = Customer.objects.get(pk=customer_id)
    except Customer.DoesNotExist:
        logger.warning('Customer %s no longer exists', customer_id)
        return {'status': 'skipped'}

    if not customer.phone:
        logger.warning('Customer %s has no phone on file', customer_id)
        return {'status': 'skipped'}

    message = f'Your order is on the way. Tracking: {tracking_code}'
    logger.info('Sending delivery SMS phone=%s tracking=%s', customer.phone, tracking_code)

    try:
        send_sms(customer.phone, message)
    except Exception as exc:
        logger.exception('SMS delivery failed for customer %s', customer_id)
        raise self.retry(exc=exc)

    return {'status': 'sent', 'customer_id': customer_id}

