def update_own_profile(payload: dict, customer: Customer = Depends(get_current_customer)):
    allowed = {'first_name', 'last_name', 'phone', 'email'}
    unknown = set(payload) - allowed
    if unknown:
        raise HTTPException(status_code=422, detail=f'Unsupported fields: {sorted(unknown)}')

