import secrets

from django.contrib.auth.decorators import login_required
from django.http import JsonResponse
from django.utils import timezone
from django.views.decorators.http import require_POST

from app.models import ApiKey


@require_POST
@login_required
def rotate_api_key(request, key_id):
    try:
        api_key = ApiKey.objects.get(pk=key_id, user=request.user)
    except ApiKey.DoesNotExist:
        return JsonResponse({'error': 'not found'}, status=404)

    if api_key.revoked:
        return JsonResponse({'error': 'key already revoked'}, status=409)

    new_value = 'sk_live_' + secrets.token_urlsafe(32)
    api_key.key = new_value
    api_key.rotated_at = timezone.now()
    api_key.save(update_fields=['key', 'rotated_at'])

    return JsonResponse(
        {
            'id': api_key.id,
            'label': api_key.label,
            'rotated_at': api_key.rotated_at.isoformat(),
            'message': 'Key rotated. Retrieve the new value from the secure vault.',
        }
    )
